:root {
    --bg-primary: #0f172a;
    --bg-secondary: #1e293b;
    --bg-tertiary: #334155;
    --text-primary: #f1f5f9;
    --text-secondary: #cbd5e1;
    --accent: #3b82f6;
    --accent-hover: #60a5fa;
    --accent-focus: #93c5fd;
    --border: #475569;
    --border-light: #64748b;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    background-color: var(--bg-primary);
    color: var(--text-primary);
    line-height: 1.6;
}

.page-wrapper {
    max-width: 56rem;
    margin: 0 auto;
    padding: 2rem 1.5rem;
}

/* Header */
header {
    text-align: center;
    margin-bottom: 3rem;
    padding-bottom: 2rem;
    border-bottom: 1px solid var(--border);
}

h1 {
    font-size: 2.5rem;
    font-weight: 700;
    margin-bottom: 0.5rem;
    color: var(--accent);
}

.subtitle {
    font-size: 1.125rem;
    color: var(--text-secondary);
}

/* Main content */
main {
    min-height: 60vh;
}

.faq-section {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

/* Example containers */
.example {
    background-color: var(--bg-secondary);
    border: 1px solid var(--border);
    border-radius: 0.5rem;
    overflow: hidden;
    transition: all 0.2s ease;
}

.example:hover {
    border-color: var(--accent);
    box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
}

/* Question styling */
.example h2 {
    margin: 0;
}

.faq-trigger {
    width: 100%;
    padding: 1.5rem;
    background-color: transparent;
    border: none;
    color: var(--text-primary);
    font-size: 1rem;
    font-weight: 600;
    text-align: left;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    transition: all 0.2s ease;
}

.faq-trigger:hover {
    background-color: var(--bg-tertiary);
    color: var(--accent-hover);
}

.faq-trigger:focus-visible {
    outline: 2px solid var(--accent-focus);
    outline-offset: 2px;
}

/* Arrow icon that rotates */
.faq-trigger::after {
    content: '';
    display: inline-block;
    width: 1.25rem;
    height: 1.25rem;
    background-image: url('data:image/svg+xml;charset=utf-8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg>');
    background-repeat: no-repeat;
    background-position: center;
    background-size: contain;
    flex-shrink: 0;
    transition: transform 0.3s ease;
}

.faq-trigger[aria-expanded="true"]::after {
    transform: rotate(180deg);
}

/* Answer content */
.details {
    padding: 1.5rem;
    border-top: 1px solid var(--border);
    background-color: var(--bg-primary);
}

.details p {
    color: var(--text-secondary);
    margin: 0;
}

/* Hidden state */
.details[hidden] {
    display: none;
}

/* Footer */
footer {
    margin-top: 3rem;
    padding-top: 2rem;
    border-top: 1px solid var(--border);
    text-align: center;
    color: var(--text-secondary);
    font-size: 0.875rem;
}

/* Responsive design */
@media (max-width: 640px) {
    .page-wrapper {
        padding: 1.5rem 1rem;
    }

    h1 {
        font-size: 1.875rem;
    }

    .subtitle {
        font-size: 1rem;
    }

    .faq-trigger {
        padding: 1rem;
    }

    .details {
        padding: 1rem;
    }
}

/* High contrast mode support */
@media (prefers-contrast: more) {
    .faq-trigger {
        border-bottom: 2px solid var(--accent);
    }

    .example {
        border-width: 2px;
    }
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }

    .faq-trigger::after {
        transition: none;
    }
}
