const { chromium } = require('playwright');
const fs = require('fs');

async function verify() {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  const html = fs.readFileSync('./index.html', 'utf-8');
  await page.setContent(html, { waitUntil: 'load' });
  await page.waitForTimeout(100);

  // Verify semantic structure
  const checks = await page.evaluate(() => {
    const results = {};

    // Check for proper landmarks
    results.main = !!document.querySelector('main');
    results.header = !!document.querySelector('header');
    results.footer = !!document.querySelector('footer');
    results.h1 = document.querySelectorAll('h1').length;

    // Check disclosure widget semantics
    const triggers = document.querySelectorAll('.faq-trigger');
    results.triggerCount = triggers.length;
    results.allTriggersAreButtons = Array.from(triggers).every(t => t.tagName === 'BUTTON');
    results.allTriggersHaveAriaExpanded = Array.from(triggers).every(t => t.hasAttribute('aria-expanded'));
    results.allTriggersInitiallyCollapsed = Array.from(triggers).every(t => t.getAttribute('aria-expanded') === 'false');

    // Check panels are hidden initially
    const panels = document.querySelectorAll('.details');
    results.panelCount = panels.length;
    results.allPanelsHidden = Array.from(panels).every(p => p.hidden === true);

    // Check example class usage
    const examples = document.querySelectorAll('.example');
    results.exampleCount = examples.length;

    // Verify heading levels
    const h2s = document.querySelectorAll('h2');
    results.h2Count = h2s.length;

    // Check for skip link (if present - optional but good)
    results.skipLink = !!document.querySelector('a[href="#main"]');

    return results;
  });

  await browser.close();

  console.log('Semantic Verification Results:');
  console.log(JSON.stringify(checks, null, 2));

  // Report any issues
  const issues = [];
  if (!checks.main) issues.push('Missing <main> landmark');
  if (!checks.header) issues.push('Missing <header> landmark');
  if (!checks.footer) issues.push('Missing <footer> landmark');
  if (checks.h1 !== 1) issues.push(`Expected 1 h1, found ${checks.h1}`);
  if (!checks.allTriggersAreButtons) issues.push('Not all triggers are <button> elements');
  if (!checks.allTriggersHaveAriaExpanded) issues.push('Not all triggers have aria-expanded');
  if (!checks.allTriggersInitiallyCollapsed) issues.push('Not all triggers are initially collapsed');
  if (!checks.allPanelsHidden) issues.push('Not all panels are hidden initially');

  if (issues.length > 0) {
    console.log('\nSemantic Issues Found:');
    issues.forEach(issue => console.log('  - ' + issue));
    process.exit(1);
  } else {
    console.log('\n✓ All semantic checks passed');
    process.exit(0);
  }
}

verify().catch(e => {
  console.error('Verification error:', e.message);
  process.exit(1);
});
