<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Cats FAQ - Frequently Asked Questions</title>
    <style>
        /* Dark theme FAQ styles */

        :root {
            --bg-primary: #0f172a;
            --bg-secondary: #1e293b;
            --bg-tertiary: #334155;
            --text-primary: #f1f5f9;
            --text-secondary: #cbd5e1;
            --accent: #3b82f6;
            --accent-hover: #60a5fa;
            --accent-focus: #93c5fd;
            --border: #475569;
            --border-light: #64748b;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        html {
            scroll-behavior: smooth;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
            background-color: var(--bg-primary);
            color: var(--text-primary);
            line-height: 1.6;
        }

        .page-wrapper {
            max-width: 56rem;
            margin: 0 auto;
            padding: 2rem 1.5rem;
        }

        /* Header */
        header {
            text-align: center;
            margin-bottom: 3rem;
            padding-bottom: 2rem;
            border-bottom: 1px solid var(--border);
        }

        h1 {
            font-size: 2.5rem;
            font-weight: 700;
            margin-bottom: 0.5rem;
            color: var(--accent);
        }

        .subtitle {
            font-size: 1.125rem;
            color: var(--text-secondary);
        }

        /* Main content */
        main {
            min-height: 60vh;
        }

        .faq-section {
            display: flex;
            flex-direction: column;
            gap: 1rem;
        }

        /* Example containers */
        .example {
            background-color: var(--bg-secondary);
            border: 1px solid var(--border);
            border-radius: 0.5rem;
            overflow: hidden;
            transition: all 0.2s ease;
        }

        .example:hover {
            border-color: var(--accent);
            box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
        }

        /* Question styling */
        .example h2 {
            margin: 0;
        }

        .faq-trigger {
            width: 100%;
            padding: 1.5rem;
            background-color: transparent;
            border: none;
            color: var(--text-primary);
            font-size: 1rem;
            font-weight: 600;
            text-align: left;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 1rem;
            transition: all 0.2s ease;
        }

        .faq-trigger:hover {
            background-color: var(--bg-tertiary);
            color: var(--accent-hover);
        }

        .faq-trigger:focus-visible {
            outline: 2px solid var(--accent-focus);
            outline-offset: 2px;
        }

        /* Arrow icon that rotates */
        .faq-trigger::after {
            content: '';
            display: inline-block;
            width: 1.25rem;
            height: 1.25rem;
            background-image: url('data:image/svg+xml;charset=utf-8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg>');
            background-repeat: no-repeat;
            background-position: center;
            background-size: contain;
            flex-shrink: 0;
            transition: transform 0.3s ease;
        }

        .faq-trigger[aria-expanded="true"]::after {
            transform: rotate(180deg);
        }

        /* Answer content */
        .details {
            padding: 1.5rem;
            border-top: 1px solid var(--border);
            background-color: var(--bg-primary);
        }

        .details p {
            color: var(--text-secondary);
            margin: 0;
        }

        /* Hidden state */
        .details[hidden] {
            display: none;
        }

        /* Footer */
        footer {
            margin-top: 3rem;
            padding-top: 2rem;
            border-top: 1px solid var(--border);
            text-align: center;
            color: var(--text-secondary);
            font-size: 0.875rem;
        }

        /* Responsive design */
        @media (max-width: 640px) {
            .page-wrapper {
                padding: 1.5rem 1rem;
            }

            h1 {
                font-size: 1.875rem;
            }

            .subtitle {
                font-size: 1rem;
            }

            .faq-trigger {
                padding: 1rem;
            }

            .details {
                padding: 1rem;
            }
        }

        /* High contrast mode support */
        @media (prefers-contrast: more) {
            .faq-trigger {
                border-bottom: 2px solid var(--accent);
            }

            .example {
                border-width: 2px;
            }
        }

        /* Reduced motion support */
        @media (prefers-reduced-motion: reduce) {
            * {
                animation-duration: 0.01ms !important;
                animation-iteration-count: 1 !important;
                transition-duration: 0.01ms !important;
            }

            .faq-trigger::after {
                transition: none;
            }
        }
    </style>
</head>
<body>
    <div class="page-wrapper">
        <header>
            <h1>Cats FAQ</h1>
            <p class="subtitle">Everything you need to know about cats</p>
        </header>

        <main>
            <section class="faq-section">
                <div class="example">
                    <h2>
                        <button type="button" class="faq-trigger" aria-expanded="false">
                            Why do cats purr?
                        </button>
                    </h2>
                    <div class="details">
                        <p>Cats purr for many reasons — contentment, self-soothing, and healing. The sound comes from rapid contractions of their laryngeal muscles. Interestingly, cats also purr when they're injured or in pain, which may help them heal faster.</p>
                    </div>
                </div>

                <div class="example">
                    <h2>
                        <button type="button" class="faq-trigger" aria-expanded="false">
                            How many hours a day do cats sleep?
                        </button>
                    </h2>
                    <div class="details">
                        <p>Cats are champion sleepers, spending 12 to 16 hours sleeping each day — and some cats sleep up to 20 hours daily. This is an evolutionary adaptation from their wild ancestors who conserved energy between hunts. Cats are crepuscular animals, meaning they're most active during dawn and dusk.</p>
                    </div>
                </div>

                <div class="example">
                    <h2>
                        <button type="button" class="faq-trigger" aria-expanded="false">
                            Do cats really have nine lives?
                        </button>
                    </h2>
                    <div class="details">
                        <p>While cats don't literally have nine lives, they are remarkably agile and have exceptional reflexes that help them survive falls. Their flexible spine, loose skin, and powerful legs allow them to land on their feet in most situations. However, they're still vulnerable to injury and illness like any other animal.</p>
                    </div>
                </div>

                <div class="example">
                    <h2>
                        <button type="button" class="faq-trigger" aria-expanded="false">
                            What does a cat's tail movement mean?
                        </button>
                    </h2>
                    <div class="details">
                        <p>A cat's tail is a primary communication tool. A slow swish indicates curiosity or mild interest, while rapid thrashing suggests anger or irritation. A tail held straight up shows confidence and friendliness, whereas a puffed tail signals fear or aggression. A tail wrapped around a person indicates affection and trust.</p>
                    </div>
                </div>

                <div class="example">
                    <h2>
                        <button type="button" class="faq-trigger" aria-expanded="false">
                            Why do cats knead with their paws?
                        </button>
                    </h2>
                    <div class="details">
                        <p>Kneading — pushing their paws alternately on soft surfaces — is a leftover behavior from kittenhood. Kittens knead their mother while nursing to stimulate milk flow. Adult cats continue this behavior when they're content and comfortable. Some cats also knead before sleep or when claiming a spot as theirs by releasing scent glands in their paws.</p>
                    </div>
                </div>

                <div class="example">
                    <h2>
                        <button type="button" class="faq-trigger" aria-expanded="false">
                            Can cats see in the dark?
                        </button>
                    </h2>
                    <div class="details">
                        <p>Cats have excellent night vision and can see in light levels six times lower than what humans need. They have more rod cells in their eyes than humans, and their eyes have a reflective layer called the tapetum lucidum that amplifies light. However, they can't see in complete darkness — they still need some ambient light.</p>
                    </div>
                </div>

                <div class="example">
                    <h2>
                        <button type="button" class="faq-trigger" aria-expanded="false">
                            How long do cats typically live?
                        </button>
                    </h2>
                    <div class="details">
                        <p>The average domestic cat lives 12 to 18 years, though some cats live into their 20s with proper care. Indoor cats generally live longer than outdoor cats due to reduced exposure to dangers. Factors affecting lifespan include diet, exercise, healthcare, genetics, and environment. Some breeds, like the Siamese, are known for particularly long lifespans.</p>
                    </div>
                </div>

                <div class="example">
                    <h2>
                        <button type="button" class="faq-trigger" aria-expanded="false">
                            Why do cats have whiskers?
                        </button>
                    </h2>
                    <div class="details">
                        <p>Whiskers are highly sensitive tactile hairs that help cats navigate their environment. Each whisker is connected to nerve endings that detect even slight changes in air pressure and vibrations. Cats use whiskers to gauge whether they can fit through tight spaces, detect prey movement, and maintain balance in darkness. They're also an indicator of a cat's mood.</p>
                    </div>
                </div>
            </section>
        </main>

        <footer>
            <p>&copy; 2024 Cats FAQ. Learn more about our feline friends.</p>
        </footer>
    </div>

    <script>
        /**
         * Initialize disclosure widgets for FAQ
         * Collapses all panels on page load and sets up click handlers
         */
        function initializeDisclosures() {
            const triggers = document.querySelectorAll('.faq-trigger');

            triggers.forEach((btn) => {
                // Get the panel (details div) that follows the h2 containing the button
                const panel = btn.closest('h2').nextElementSibling;

                if (!panel || !panel.classList.contains('details')) {
                    console.warn('Panel not found for trigger:', btn);
                    return;
                }

                // Initialize: set collapsed state
                btn.setAttribute('aria-expanded', 'false');
                panel.hidden = true;

                // Handle clicks
                btn.addEventListener('click', () => {
                    const isOpen = btn.getAttribute('aria-expanded') === 'true';
                    btn.setAttribute('aria-expanded', String(!isOpen));
                    panel.hidden = isOpen;
                });

                // Optional: Allow Escape to collapse
                btn.addEventListener('keydown', (event) => {
                    if (event.key === 'Escape' && btn.getAttribute('aria-expanded') === 'true') {
                        btn.setAttribute('aria-expanded', 'false');
                        panel.hidden = true;
                        btn.focus();
                    }
                });
            });
        }

        // Initialize when DOM is ready
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', initializeDisclosures);
        } else {
            initializeDisclosures();
        }
    </script>
</body>
</html>
